#[allow(clippy::too_many_arguments)]
pub(crate) fn console_json_router_with_runtime_events_and_policy(
    decisions: RuntimeDecisionState,
    runtime: MobRuntime,
    module_runtime: Option<std::sync::Arc<tokio::sync::Mutex<MetaRuntimeHandle>>>,
    contact_directory: Option<ContactDirectory>,
    event_log: Option<std::sync::Arc<dyn EventLogStore>>,
    gateway_peer_keys: Option<crate::auth::peer_keys::GatewayPeerKeys>,
    console_events: Option<ConsoleEventStore>,
    console_log_store: Option<std::sync::Arc<dyn ConsoleLogStore>>,
    mob_events: Option<MobEventsStore>,
    metadata_table: Option<std::sync::Arc<RuntimeMetadataTable>>,
    identity_runtime: Option<crate::identity_first::PublicIdentityRuntime>,
    visibility_policy: Arc<dyn ConsoleVisibilityPolicy>,
    access: Option<AccessController>,
    memory_panel: Option<Arc<dyn crate::memory::capabilities::MemoryPanelStore>>,
    operator_resolver: Option<Arc<crate::memory::coordinator::ConsolePrincipalOperatorResolver>>,
    identity_roster: Option<Arc<crate::identity_first::MutableRosterProvider>>,
    workgraph: Option<meerkat::WorkGraphService>,
    topology: Option<crate::topology_control::TopologyRuntimeHandle>,
    job_health_projection: Option<Arc<std::sync::RwLock<Option<serde_json::Value>>>>,
    shared_aggregator: Option<MetaConsoleAggregator>,
    governed_ingress: crate::console_governed_ingress::ConsoleGovernedIngressSlot,
    session_fences: crate::auth::session_fence::ConsoleSessionFences,
    mob_announcements: crate::mob_announcements::AnnouncementSlot,
) -> Router {
    let console_aggregator = shared_aggregator.or_else(|| {
        console_events.clone().map(|events| {
            if let Some(store) = console_log_store {
                let aggregator = MetaConsoleAggregator::new(store);
                aggregator.register_owned_runtime_handles_with_policy(
                    "default",
                    "",
                    runtime.clone(),
                    identity_runtime.clone(),
                    events,
                    visibility_policy.clone(),
                );
                aggregator
            } else {
                let aggregator = MetaConsoleAggregator::in_memory();
                aggregator.register_owned_runtime_handles_with_policy(
                    "default",
                    "",
                    runtime.clone(),
                    identity_runtime.clone(),
                    events,
                    visibility_policy.clone(),
                );
                aggregator
            }
        })
    });
    let snapshot_read_model = ConsoleSnapshotReadModel::default();
    snapshot_read_model.refresh_soon(
        runtime.clone(),
        identity_runtime
            .as_ref()
            .map(|identity_runtime| Arc::clone(identity_runtime.runtime())),
    );
    // Fall back to the mob runtime's bootstrap-time service so routers built
    // through the thinner constructors still expose workgraph.
    let workgraph = workgraph.or_else(|| runtime.workgraph_service());
    console_json_router_with_state(ConsoleJsonState {
        decisions,
        session_fences,
        runtime: Some(runtime),
        module_runtime,
        contact_directory,
        event_log,
        gateway_peer_keys,
        identity_runtime,
        console_events,
        console_aggregator,
        mob_events,
        metadata_table,
        visibility_policy,
        snapshot_read_model,
        access,
        memory_panel,
        operator_resolver,
        identity_roster,
        workgraph,
        topology,
        job_health_projection,
        governed_ingress,
        mob_announcements,
    })
}

pub fn console_frontend_router() -> Router {
    Router::new()
        .route("/", get(|| async { Redirect::temporary("/console") }))
        .route("/favicon.ico", get(|| async { StatusCode::NO_CONTENT }))
        .route("/console", get(console_frontend_index_handler))
        .route("/console/", get(console_frontend_index_handler))
        .route(
            "/console/assets/console-app.js",
            get(console_frontend_app_js_handler),
        )
        .route(
            "/console/assets/console-app.css",
            get(console_frontend_app_css_handler),
        )
}

/// How often a gating stream re-checks access and applies expiry without a
/// change wake.
const GATING_STREAM_RECHECK: Duration = Duration::from_secs(15);

fn gating_audit_entry_origin(entry: &crate::runtime::GatingAuditEntry) -> Option<&str> {
    entry
        .detail
        .get("origin")
        .and_then(|origin| origin.get("identity"))
        .and_then(Value::as_str)
}

/// Whether a caller may see an audit entry: entries recorded with an origin
/// are visible only to callers that may view that origin's agent.
fn gating_audit_entry_visible(
    entry: &crate::runtime::GatingAuditEntry,
    access_view: Option<&AccessView>,
) -> bool {
    entry
        .detail
        .get("origin")
        .and_then(|origin| origin.get("identity"))
        .and_then(Value::as_str)
        .is_none_or(|identity| access_view.is_none_or(|view| view.can_view_agent(identity)))
}

/// Live gating change notifications for the console. A connection starts with
/// `gating.resync_required` (`initial_sync`). Afterwards `gating.changed`
/// means an audit entry the caller may see was recorded; the caller pulls it
/// through `meta/gating/audit` with its cursor. Frames carry no gate IDs or
/// outcomes, and a frame is never authorization to act. `gating.view` and the
/// origin audience are re-checked on every wake from the live access
/// configuration; losing `gating.view` ends the stream with
/// `gating.access_revoked`. A caller's token the verifier no longer accepts
/// ends it without a frame.
async fn console_gating_stream_handler(
    State(state): State<ConsoleJsonState>,
    shutdown: Option<axum::Extension<crate::http_sse::StreamShutdown>>,
    headers: HeaderMap,
    uri: Uri,
) -> axum::response::Response {
    let crate::http_sse::SseCaller {
        access_view,
        mut authentication,
    } = match crate::http_sse::sse_access_context(
        Some(&state.decisions),
        &state.session_fences,
        state.access.as_ref(),
        &headers,
        &uri,
    ) {
        Ok(caller) => caller,
        Err(()) => {
            return (
                StatusCode::UNAUTHORIZED,
                Json(json!({ "error": "unauthorized", "reason": "gating stream requires a valid auth token" })),
            )
                .into_response();
        }
    };
    if access_view
        .as_ref()
        .is_some_and(|view| view.enforced() && !view.allows(ACTION_GATING_VIEW))
    {
        return (
            StatusCode::FORBIDDEN,
            Json(json!({ "error": "access_denied", "action": ACTION_GATING_VIEW })),
        )
            .into_response();
    }
    let Some(owner) = state.module_runtime.clone() else {
        return (
            StatusCode::NOT_FOUND,
            Json(json!({ "error": "gating_unavailable" })),
        )
            .into_response();
    };
    let subject = access_view
        .as_ref()
        .and_then(|view| view.subject().map(ToString::to_string));
    // Keep an installed controller even while it is disabled: enabling a
    // policy later must reach this stream. Priming is a no-op while it is
    // disabled.
    let access = state.access.clone();
    let runtime = state.runtime.clone();
    // Resolve origin labels and roles from the live roster before any
    // visibility decision, exactly as the other console streams do.
    if let (Some(runtime), Some(controller)) = (&runtime, &access) {
        prime_access_cache_from_runtime(runtime, controller).await;
    }
    let (mut receiver, mut cursor) = {
        let mut owner = owner.lock().await;
        let receiver = owner.subscribe_gating_changes();
        let cursor = owner
            .gating_audit_after(None)
            .entries
            .last()
            .map(|entry| entry.audit_id.clone());
        (receiver, cursor)
    };
    let mut recheck = tokio::time::interval_at(
        tokio::time::Instant::now() + GATING_STREAM_RECHECK,
        GATING_STREAM_RECHECK,
    );
    recheck.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Delay);
    let mut shutdown = shutdown.map(|axum::Extension(shutdown)| shutdown);
    let stream = async_stream::stream! {
        yield Ok::<_, std::convert::Infallible>(
            axum::response::sse::Event::default()
                .event("gating.resync_required")
                .data(json!({ "reason": "initial_sync" }).to_string()),
        );
        loop {
            // A wake, a lagged wake and the periodic re-check are handled
            // alike: re-read through the cursor (which also applies expiry),
            // then decide with a fresh view. Lag carries no information of
            // its own, so it never produces a frame by itself.
            // The caller's lapsed token ends the stream, even while nothing
            // else wakes it, and so does the gateway's shutdown.
            let ended = tokio::select! {
                () = crate::http_sse::authentication_lapsed(authentication.as_mut()) => true,
                () = crate::http_sse::stream_shutdown_begun(shutdown.as_mut()) => true,
                received = receiver.recv() => matches!(
                    received,
                    Err(tokio::sync::broadcast::error::RecvError::Closed)
                ),
                _ = recheck.tick() => false,
            };
            if ended {
                break;
            }
            let page = owner.lock().await.gating_audit_after(cursor.as_deref());
            if let (Some(runtime), Some(controller)) = (&runtime, &access) {
                let probe = controller.view_for_subject(subject.as_deref());
                if page
                    .entries
                    .iter()
                    .filter_map(gating_audit_entry_origin)
                    .any(|identity| !probe.knows_agent(identity))
                {
                    prime_access_cache_from_runtime(runtime, controller).await;
                }
            }
            if !crate::http_sse::still_authenticated(authentication.as_mut()) {
                break;
            }
            // The view is derived after the last await, from the live
            // configuration and attribute cache.
            let view = access
                .as_ref()
                .map(|controller| controller.view_for_subject(subject.as_deref()));
            if view
                .as_ref()
                .is_some_and(|view| view.enforced() && !view.allows(ACTION_GATING_VIEW))
            {
                yield Ok(axum::response::sse::Event::default()
                    .event("gating.access_revoked")
                    .data("{}"));
                break;
            }
            if page.gap {
                cursor = page.entries.last().map(|entry| entry.audit_id.clone());
                yield Ok(axum::response::sse::Event::default()
                    .event("gating.resync_required")
                    .data(json!({ "reason": "gap" }).to_string()));
                continue;
            }
            if let Some(last) = page.entries.last() {
                cursor = Some(last.audit_id.clone());
            }
            if page
                .entries
                .iter()
                .any(|entry| gating_audit_entry_visible(entry, view.as_ref()))
            {
                yield Ok(axum::response::sse::Event::default()
                    .event("gating.changed")
                    .data("{}"));
            }
        }
    };
    axum::response::sse::Sse::new(stream)
        .keep_alive(axum::response::sse::KeepAlive::default())
        .into_response()
}

fn console_json_router_with_state(state: ConsoleJsonState) -> Router {
    let router = Router::new()
        .route("/console/gating/stream", get(console_gating_stream_handler))
        .route("/console/experience", get(console_json_handler))
        .route("/console/modules", get(console_json_handler))
        .route("/console/identities", get(console_identities_handler))
        .route("/console/timeline", get(console_timeline_handler))
        .route("/console/mcp-apps/resolve", post(mcp_apps::resolve))
        .route(
            "/console/mcp-apps/read-resource",
            post(mcp_apps::read_resource),
        )
        .route("/console/mcp-apps/call-tool", post(mcp_apps::call_tool))
        .route(
            "/console/timeline/stream",
            get(console_timeline_stream_handler),
        )
        .route(
            "/console/identity/{identity}/stream",
            get(console_identity_timeline_stream_handler),
        )
        .route("/console/send", post(console_send_handler))
        .route("/console/send/recover", post(console_send_recover_handler))
        .route("/console/rpc", post(console_rpc_handler))
        .route(
            "/console/rpc/multipart",
            post(console_rpc_multipart_handler)
                .layer(DefaultBodyLimit::max(MAX_MULTIPART_BODY_BYTES)),
        )
        .route("/blobs/{blob_id}", get(blob_get_handler));
    router.with_state(state)
}

pub async fn console_json_handler(
    State(state): State<ConsoleJsonState>,
    voice: Option<axum::Extension<crate::console_voice::ConsoleVoiceController>>,
    headers: HeaderMap,
    uri: Uri,
) -> impl IntoResponse {
    let mut path = uri
        .path_and_query()
        .map(|path_and_query| path_and_query.as_str().to_string())
        .unwrap_or_else(|| uri.path().to_string());

    // If the request carries a Bearer token and the URL doesn't already have
    // an auth_token query param, inject it so the console-ingress auth
    // resolver can validate it through the existing query-param path.
    //
    // JWT tokens use base64url characters (A-Za-z0-9_-.) plus optional '='
    // padding. We percent-encode the bearer when injecting so opaque
    // bearer tokens containing `&`, `=`, `+`, `%`, etc. (legal under
    // RFC 6750 §2.1) survive the round trip — pre-fix, an `&` made
    // injection skip and authentication fail. Substring detection of
    // an existing `auth_token=` is now key-aware via form_urlencoded
    // so `xauth_token=` doesn't masquerade as the real key.
    let already_has_token = path
        .split_once('?')
        .map(|(_, q)| form_urlencoded::parse(q.as_bytes()).any(|(key, _)| key == "auth_token"))
        .unwrap_or(false);
    if !already_has_token
        && let Some(bearer) = headers
            .get(header::AUTHORIZATION)
            .and_then(|v| v.to_str().ok())
            .and_then(extract_bearer_token_from_header)
    {
        let encoded: String = form_urlencoded::byte_serialize(bearer.as_bytes()).collect();
        let sep = if path.contains('?') { '&' } else { '?' };
        path = format!("{path}{sep}auth_token={encoded}");
    }

    let config_module_ids: Vec<String> = state
        .decisions
        .modules
        .iter()
        .map(|m| m.id.clone())
        .collect();
    // Identities whose rows this read answers pending: their binding moved
    // and the read model had not re-collected them by the refresh deadline.
    let mut pending_identities = BTreeSet::new();
    let live_snapshot = match &state.runtime {
        Some(runtime) => {
            let identity_runtime = state
                .identity_runtime
                .as_ref()
                .map(crate::identity_first::PublicIdentityRuntime::runtime);
            state
                .snapshot_read_model
                .refresh_soon(runtime.clone(), identity_runtime.cloned());
            let (snapshot, pending) = Box::pin(build_live_snapshot(
                runtime,
                &config_module_ids,
                state.console_events.as_ref(),
                state.visibility_policy.as_ref(),
                &state.snapshot_read_model,
                identity_runtime,
            ))
            .await;
            pending_identities = pending;
            Some(snapshot)
        }
        None => match &state.console_aggregator {
            Some(aggregator) => Box::pin(build_aggregator_live_snapshot(
                aggregator,
                &config_module_ids,
            ))
            .await
            .ok(),
            None => None,
        },
    }
    .map(|mut snapshot| {
        apply_console_visibility_policy(&mut snapshot, state.visibility_policy.as_ref());
        snapshot
    });

    let panel_runtimes = match state
        .console_aggregator
        .as_ref()
        .filter(|_| state.runtime.is_none())
        .map(super::console_aggregator::MetaConsoleAggregator::panel_runtimes)
        .transpose()
    {
        Ok(runtimes) => runtimes,
        Err(_) => {
            return (
                StatusCode::SERVICE_UNAVAILABLE,
                Json(json!({"error": "Console runtime registry is unavailable"})),
            );
        }
    };
    let memory_available = state.memory_panel.is_some()
        || panel_runtimes
            .as_ref()
            .is_some_and(|runtimes| runtimes.iter().any(|runtime| runtime.memory.is_some()));
    let workgraph_available = state.workgraph.is_some()
        || panel_runtimes.as_ref().is_some_and(|runtimes| {
            runtimes
                .iter()
                .any(|runtime| runtime.runtime.workgraph_service().is_some())
        });
    let mut response = handle_console_rest_json_route_with_pending_rows(
        &state.decisions,
        &state.session_fences,
        &ConsoleRestJsonRequest {
            method: "GET".to_string(),
            path,
            auth: None,
        },
        live_snapshot.as_ref(),
        state.access.as_ref(),
        memory_available,
        workgraph_available,
        &pending_identities,
    );
    if response.status == 200
        && uri.path() == "/console/experience"
        && let Some(auth) = console_request_auth_context(&state, &headers, &uri)
    {
        attach_console_storage_scope(&mut response.body, auth.principal.as_deref());
    }
    if response.status == 200 && uri.path() == "/console/experience" {
        attach_console_send_dedupe(&mut response.body, state.console_aggregator.as_ref());
        if let Some(runtimes) = panel_runtimes {
            response.body["panel_runtimes"] = json!(
                runtimes
                    .iter()
                    .map(shared_panels::descriptor)
                    .collect::<Vec<_>>()
            );
            // Shared stores currently support inspection only.
            response.body["workgraph"]["can_manage"] = json!(false);
        }
    }
    if response.status == 200
        && uri.path() == "/console/experience"
        && !state.decisions.console.read_only
        && let Some(voice) = voice
    {
        let auth = console_request_auth_context(&state, &headers, &uri);
        if voice.0.configured() && auth.as_ref().is_some_and(|auth| auth.principal.is_some()) {
            response.body["voice"] = json!({
                "available": false,
                "readiness_method": crate::console_voice::VOICE_READINESS_METHOD
            });
        }
    }
    let status = StatusCode::from_u16(response.status).unwrap_or(StatusCode::INTERNAL_SERVER_ERROR);
    (status, Json::<Value>(response.body))
}

/// Advertise whether the store behind `meta/console/send` keeps its dedupe
/// records across a gateway restart, read from the store actually in use.
/// The console offers "Send again" on an uncertain send (same idempotency
/// key) only when `send_dedupe.durable` is true; without an aggregator there
/// is no send path, so the section is absent.
fn attach_console_send_dedupe(experience: &mut Value, aggregator: Option<&MetaConsoleAggregator>) {
    let Some(aggregator) = aggregator else {
        return;
    };
    if let Some(object) = experience.as_object_mut() {
        object.insert(
            "send_dedupe".to_string(),
            json!({ "durable": aggregator.send_dedupe_durability().is_durable() }),
        );
    }
}

/// Storage keys are opaque projections of the authenticated runtime/principal.
/// Anonymous consoles form an explicit shared local account. The browser also
/// includes its gateway base URL, and custom hosts can supply a stricter scope.
fn attach_console_storage_scope(experience: &mut Value, principal: Option<&str>) {
    use sha2::{Digest, Sha256};
    let Some(runtime_id) = experience
        .get("runtime_id")
        .and_then(Value::as_str)
        .filter(|value| !value.trim().is_empty())
    else {
        return;
    };
    // A durable key, not a name: browsers namespace saved queues by this
    // digest, so it is unchanged by the 0.9 rename.
    let owner = json!(["mobkit-console-storage-v1", runtime_id, principal]);
    let digest = Sha256::digest(owner.to_string().as_bytes());
    experience["storage_scope"] = json!(format!("console-storage:v1:{digest:x}"));
}

pub async fn console_rpc_handler(
    State(state): State<ConsoleJsonState>,
    voice: Option<axum::Extension<crate::console_voice::ConsoleVoiceController>>,
    headers: HeaderMap,
    uri: Uri,
    Json(request): Json<Value>,
) -> impl IntoResponse {
    // Parse the request early so we can check the method for auth gating.
    let parsed_request = match serde_json::from_value::<JsonRpcRequest>(request) {
        Ok(req) => req,
        Err(_) => {
            return (
                StatusCode::OK,
                Json::<Value>(serde_json::json!({
                    "jsonrpc": JSONRPC_VERSION,
                    "id": Value::Null,
                    "error": { "code": -32600, "message": "Invalid Request" }
                })),
            );
        }
    };
    let request_method = parsed_request.method.clone();

    // Auth enforcement:
    // - When require_app_auth is true: validate bearer token (OIDC + allowlist)
    // - When require_app_auth is false: allow requests without a token.
    // - When console.read_only is true: deny mutating methods even for
    //   otherwise authorized callers.
    let auth_context = match console_request_auth_context(&state, &headers, &uri) {
        Some(context) => context,
        None => {
            return console_rpc_unauthenticated_response(parsed_request.id.unwrap_or(Value::Null));
        }
    };
    // By this point the request is always authorized:
    // - require_app_auth=true: an invalid token already returned 401 above.
    // - require_app_auth=false: all methods are permitted unconditionally.
    // Mutating methods may still be blocked by console.read_only.
    let is_authenticated = true;
    let read_only = state.decisions.console.read_only;
    // A candidate launch refuses member input and roster changes here
    // too, voice included, before anything is read or written.
    if let Some(runtime) = state.runtime.as_ref()
        && let Some(refusal) = crate::rpc::candidate_launch_refusal(
            runtime.speaks_for_composition(),
            candidate_state_dir(runtime).as_deref(),
            request_method.as_str(),
            &parsed_request.params,
            parsed_request.id.clone().unwrap_or(Value::Null),
        )
    {
        return (
            StatusCode::OK,
            Json::<Value>(response_value(refusal.id, refusal.result, refusal.error)),
        );
    }
    if request_method == crate::rpc::CONSOLE_REVOKE_SESSIONS_METHOD {
        let response =
            console_revoke_sessions_rpc(&state, &auth_context, read_only, &parsed_request);
        return (StatusCode::OK, Json::<Value>(response));
    }
    if matches!(
        request_method.as_str(),
        crate::console_voice::VOICE_OPEN_METHOD
            | crate::console_voice::VOICE_READINESS_METHOD
            | crate::console_voice::VOICE_CLOSE_METHOD
            | crate::console_voice::VOICE_ANSWER_RECEIVED_METHOD
            | crate::console_voice::VOICE_REPLACEMENT_METHOD
            | crate::console_voice::VOICE_ACTIVITY_METHOD
            | crate::console_voice::VOICE_CONTEXT_STATUS_METHOD
            | crate::console_voice::VOICE_CAPTIONS_METHOD
    ) || crate::console_voice::is_channel_method(&request_method)
    {
        let response = handle_console_voice_rpc(
            &state,
            voice.as_ref().map(|extension| &extension.0),
            &auth_context,
            parsed_request,
        )
        .await;
        return (StatusCode::OK, Json::<Value>(response));
    }
    let Some(runtime) = &state.runtime else {
        let response_value = Box::pin(handle_console_aggregator_rpc(
            state.console_aggregator.clone(),
            parsed_request,
            is_authenticated,
            read_only,
            state.access.as_ref(),
            auth_context.access_view.as_ref(),
            &auth_context.send_scope(),
        ))
        .await;
        return (StatusCode::OK, Json::<Value>(response_value));
    };

    let response_value = Box::pin(handle_console_runtime_rpc_with_visibility(
        runtime,
        state.module_runtime.clone(),
        state.contact_directory.as_ref(),
        state.gateway_peer_keys.as_ref(),
        state.console_events.clone(),
        state.console_aggregator.clone(),
        state
            .identity_runtime
            .as_ref()
            .map(|identity_runtime| Arc::clone(identity_runtime.runtime())),
        state.metadata_table.clone(),
        state.mob_events.clone(),
        state.visibility_policy.as_ref(),
        parsed_request,
        is_authenticated,
        read_only,
        auth_context.principal.as_deref(),
        state.access.as_ref(),
        auth_context.access_view.as_ref(),
        state.memory_panel.as_deref(),
        state.identity_roster.clone(),
        state.workgraph.as_ref(),
        state.topology.as_ref(),
        state.mob_announcements.get(),
        &ConsoleSendGovernance::for_request(&state, &auth_context),
        &console_topology_apply_scope(&auth_context),
    ))
    .await;
    let response_value = decorate_console_job_projection(
        response_value,
        &request_method,
        state.job_health_projection.as_ref(),
    );
    (StatusCode::OK, Json::<Value>(response_value))
}

/// Server-side bound on one readiness answer. It sits below the console's
/// own 5 s request timeout so the console receives the typed
/// `voice_readiness_timed_out` answer (retry, keep what was known) instead
/// of a transport timeout. Exceeding it is logged with the active stage.
const VOICE_READINESS_SERVER_BUDGET: Duration = Duration::from_secs(4);
/// A readiness answer slower than this is logged at warn even when positive:
/// the client's own bound is 5 s and it gates the voice button on the answer.
const VOICE_READINESS_SLOW_BUDGET: Duration = Duration::from_secs(1);

fn elapsed_ms_since(started: std::time::Instant) -> u64 {
    u64::try_from(started.elapsed().as_millis()).unwrap_or(u64::MAX)
}

#[derive(Debug)]
enum ReadinessOutcome {
    Answered(Result<crate::console_voice::VoiceReadinessReport, crate::console_voice::VoiceError>),
    /// The budget expired; this caller's hold on the check was dropped.
    TimedOut,
}

/// One caller's readiness answer and what the check had done when it
/// answered or the budget expired.
#[derive(Debug)]
struct ReadinessAnswer {
    outcome: ReadinessOutcome,
    /// `true` when this request joined a check already in flight.
    joined: bool,
    budget: Duration,
    elapsed: Duration,
    trace: Option<crate::console_voice::readiness_trace::VoiceReadinessTraceSnapshot>,
}

/// Start or join the readiness check and bound it by `budget`. On expiry
/// the hold is dropped; the shared check is cancelled once nobody holds it.
async fn readiness_within_budget(
    controller: &crate::console_voice::ConsoleVoiceController,
    principal: &str,
    identity: &str,
    budget: Duration,
) -> ReadinessAnswer {
    let started = std::time::Instant::now();
    let flight = match controller.readiness_flight(principal, identity) {
        Ok(flight) => flight,
        Err(failure) => {
            return ReadinessAnswer {
                outcome: ReadinessOutcome::Answered(Err(failure)),
                joined: false,
                budget,
                elapsed: started.elapsed(),
                trace: None,
            };
        }
    };
    let crate::console_voice::ReadinessFlight {
        trace,
        joined,
        result,
    } = flight;
    let outcome = match tokio::time::timeout(budget, result).await {
        Ok(answer) => ReadinessOutcome::Answered(answer),
        Err(_) => ReadinessOutcome::TimedOut,
    };
    ReadinessAnswer {
        outcome,
        joined,
        budget,
        elapsed: started.elapsed(),
        trace: Some(trace.snapshot()),
    }
}

fn log_voice_readiness(identity: &str, pre_check_ms: u64, answer: &ReadinessAnswer) {
    let elapsed_ms = u64::try_from(answer.elapsed.as_millis()).unwrap_or(u64::MAX);
    let slow = answer.elapsed > VOICE_READINESS_SLOW_BUDGET;
    let stages = answer
        .trace
        .as_ref()
        .map(ToString::to_string)
        .unwrap_or_default();
    let joined = answer.joined;
    match &answer.outcome {
        ReadinessOutcome::TimedOut => {
            let active_stage = answer
                .trace
                .as_ref()
                .and_then(|trace| trace.active)
                .map_or("none", |stage| stage.as_str());
            tracing::warn!(
                target: "meerkat_meta::console_voice::timing",
                identity,
                elapsed_ms,
                pre_check_ms,
                budget_ms = u64::try_from(answer.budget.as_millis()).unwrap_or(u64::MAX),
                active_stage,
                stages = %stages,
                joined,
                "console voice readiness budget exceeded; answered voice_readiness_timed_out"
            );
        }
        ReadinessOutcome::Answered(Err(failure)) => tracing::warn!(
            target: "meerkat_meta::console_voice::timing",
            identity,
            elapsed_ms,
            pre_check_ms,
            slow,
            cause = ?failure,
            stages = %stages,
            joined,
            "console voice readiness not available"
        ),
        ReadinessOutcome::Answered(Ok(report)) if !report.available => tracing::warn!(
            target: "meerkat_meta::console_voice::timing",
            identity,
            elapsed_ms,
            pre_check_ms,
            slow,
            cause = report.reason.unwrap_or("host reports unavailable"),
            stages = %stages,
            joined,
            "console voice readiness not available"
        ),
        ReadinessOutcome::Answered(Ok(_)) if slow => tracing::warn!(
            target: "meerkat_meta::console_voice::timing",
            identity,
            elapsed_ms,
            pre_check_ms,
            budget_ms = VOICE_READINESS_SLOW_BUDGET.as_millis() as u64,
            stages = %stages,
            joined,
            "console voice readiness available but slow"
        ),
        ReadinessOutcome::Answered(Ok(_)) => tracing::info!(
            target: "meerkat_meta::console_voice::timing",
            identity,
            elapsed_ms,
            pre_check_ms,
            stages = %stages,
            joined,
            "console voice readiness available"
        ),
    }
}

#[cfg(test)]
#[allow(clippy::expect_used)]
mod voice_readiness_budget_tests {
    use super::*;
    use crate::console_voice::readiness_test_support::ParkedReadyHost;
    use crate::console_voice::readiness_trace::VoiceReadinessStage;
    use std::sync::atomic::Ordering;

    #[derive(Clone, Default)]
    struct Capture(Arc<std::sync::Mutex<Vec<u8>>>);

    impl std::io::Write for Capture {
        fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
            self.0
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .extend_from_slice(buf);
            Ok(buf.len())
        }
        fn flush(&mut self) -> std::io::Result<()> {
            Ok(())
        }
    }

    impl<'a> tracing_subscriber::fmt::MakeWriter<'a> for Capture {
        type Writer = Capture;
        fn make_writer(&'a self) -> Self::Writer {
            self.clone()
        }
    }

    fn logged(answer: &ReadinessAnswer) -> String {
        let capture = Capture::default();
        let subscriber = tracing_subscriber::fmt()
            .with_writer(capture.clone())
            .with_ansi(false)
            .with_max_level(tracing::Level::INFO)
            .finish();
        // A second registered Dispatch keeps callsite interest from being
        // cached `never` by threads without a subscriber.
        let _anchor = tracing::Dispatch::new(tracing_subscriber::Registry::default());
        tracing::subscriber::with_default(subscriber, || {
            log_voice_readiness("agent-a", 2, answer);
        });
        let bytes = capture
            .0
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .clone();
        String::from_utf8(bytes).expect("utf8 log")
    }

    #[tokio::test]
    async fn an_expired_budget_names_the_active_stage_answers_typed_and_cancels_the_check() {
        let host = ParkedReadyHost::new(VoiceReadinessStage::DurableSource);
        let controller = host.controller();
        let answer =
            readiness_within_budget(&controller, "alice", "agent-a", Duration::from_millis(50))
                .await;
        assert!(
            matches!(answer.outcome, ReadinessOutcome::TimedOut),
            "{answer:?}"
        );
        let trace = answer.trace.as_ref().expect("trace");
        assert_eq!(trace.active, Some(VoiceReadinessStage::DurableSource));
        assert!(
            trace
                .elapsed_of(VoiceReadinessStage::DurableSource)
                .expect("durable source time")
                >= Duration::from_millis(40),
            "{trace}"
        );
        assert!(
            trace.elapsed_of(VoiceReadinessStage::Target).is_some(),
            "{trace}"
        );
        assert_eq!(
            host.cancelled.load(Ordering::SeqCst),
            1,
            "the only caller gave up, so the check was dropped"
        );
        let log = logged(&answer);
        assert!(log.contains("WARN"), "{log}");
        assert!(log.contains("active_stage=\"durable_source\""), "{log}");
        assert!(log.contains("durable_source="), "{log}");
        assert!(log.contains("(active)"), "{log}");
        assert!(log.contains("budget_ms=50"), "{log}");
        assert_eq!(
            crate::console_voice::VoiceError::ReadinessTimedOut
                .rpc_error()
                .data,
            Some(json!({"kind":"voice_readiness_timed_out"}))
        );
    }

    #[tokio::test]
    async fn an_answer_within_budget_logs_every_stage_at_info() {
        let host = ParkedReadyHost::new(VoiceReadinessStage::Credential);
        host.release.add_permits(1);
        let controller = host.controller();
        let answer =
            readiness_within_budget(&controller, "alice", "agent-a", Duration::from_secs(5)).await;
        assert!(
            matches!(&answer.outcome, ReadinessOutcome::Answered(Ok(report)) if report.available),
            "{answer:?}"
        );
        let trace = answer.trace.as_ref().expect("trace");
        assert_eq!(trace.active, None);
        let log = logged(&answer);
        assert!(log.contains(" INFO "), "{log}");
        assert!(log.contains("console voice readiness available"), "{log}");
        assert!(log.contains("target="), "{log}");
        assert!(log.contains("credential="), "{log}");
        assert!(!log.contains("(active)"), "{log}");
        assert_eq!(host.cancelled.load(Ordering::SeqCst), 0);
    }
}

/// Wall time of every console voice control-plane verb. Status polls are
/// frequent and land at debug; every other verb lands at info.
async fn handle_console_voice_rpc(
    state: &ConsoleJsonState,
    controller: Option<&crate::console_voice::ConsoleVoiceController>,
    auth: &ConsoleHttpAuthContext,
    request: JsonRpcRequest,
) -> Value {
    let method = request.method.clone();
    let channel_id = request
        .params
        .get("channel_id")
        .and_then(Value::as_str)
        .map(str::to_string);
    let started = std::time::Instant::now();
    let response = handle_console_voice_rpc_inner(state, controller, auth, request, started).await;
    let elapsed_ms = u64::try_from(started.elapsed().as_millis()).unwrap_or(u64::MAX);
    let ok = response.get("error").is_none_or(Value::is_null);
    let phase = response
        .pointer("/result/phase")
        .and_then(Value::as_str)
        .map(str::to_string);
    if method == "meta/live/status"
        || method == crate::console_voice::VOICE_CONTEXT_STATUS_METHOD
        || method == crate::console_voice::VOICE_CAPTIONS_METHOD
    {
        tracing::debug!(
            target: "meerkat_meta::console_voice::timing",
            method = %method, channel_id = ?channel_id, elapsed_ms, ok, phase = ?phase,
            "console voice rpc"
        );
    } else {
        tracing::info!(
            target: "meerkat_meta::console_voice::timing",
            method = %method, channel_id = ?channel_id, elapsed_ms, ok, phase = ?phase,
            "console voice rpc"
        );
    }
    response
}

async fn handle_console_voice_rpc_inner(
    state: &ConsoleJsonState,
    controller: Option<&crate::console_voice::ConsoleVoiceController>,
    auth: &ConsoleHttpAuthContext,
    request: JsonRpcRequest,
    request_started: std::time::Instant,
) -> Value {
    use crate::console_voice::{
        VOICE_ACTIVITY_METHOD, VOICE_ANSWER_RECEIVED_METHOD, VOICE_CAPTIONS_METHOD,
        VOICE_CLOSE_METHOD, VOICE_CONTEXT_STATUS_METHOD, VOICE_OPEN_METHOD, VOICE_READINESS_METHOD,
        VOICE_REPLACEMENT_METHOD, VoiceActivity, VoiceAnswerReceived, VoiceCaptionsRequest,
        VoiceContextStatusRequest, VoiceError, VoiceReadiness, VoiceRequest,
    };

    if request.jsonrpc != JSONRPC_VERSION || request.id.is_none() {
        return invalid_params(
            request.id.unwrap_or(Value::Null),
            "Voice lifecycle requires a JSON-RPC 2.0 request with an id",
        );
    }
    let id = request.id.unwrap_or(Value::Null);
    let error = |error: VoiceError| response_value(id.clone(), None, Some(error.rpc_error()));
    let Some(principal) = auth
        .principal
        .as_deref()
        .filter(|value| !value.trim().is_empty())
    else {
        return error(VoiceError::Unauthorized);
    };
    let retains_teardown_access = matches!(
        request.method.as_str(),
        VOICE_CLOSE_METHOD
            | "meta/live/close"
            | "meta/live/status"
            | "meta/live/playback_owner/revoke"
    );
    if !retains_teardown_access {
        // Owned status and caption reads mutate nothing.
        if state.decisions.console.read_only
            && request.method != VOICE_CONTEXT_STATUS_METHOD
            && request.method != VOICE_CAPTIONS_METHOD
        {
            return console_read_only_rpc_error(id);
        }
        if let (Some(runtime), Some(access)) = (
            state.runtime.as_ref(),
            state.access.as_ref().filter(|access| access.enabled()),
        ) {
            prime_access_cache_from_runtime(runtime, access).await;
        }
        if let Some(denial) = console_rpc_access_violation(
            auth.access_view.as_ref(),
            &request.method,
            &request.params,
        ) {
            return response_value(id, None, Some(denial));
        }
    }
    if request.method == VOICE_READINESS_METHOD {
        let parsed: VoiceReadiness = match serde_json::from_value(request.params) {
            Ok(parsed) => parsed,
            Err(_) => return error(VoiceError::InvalidRequest),
        };
        let Some(controller) = controller else {
            return response_value(
                id,
                Some(json!({"identity":parsed.identity,"available":false})),
                None,
            );
        };
        // The readiness answer is the console's gate for the voice button and
        // for every click. A negative or slow answer must leave a server-side
        // trace with its cause and the stage it spent its time in.
        let pre_check_ms = elapsed_ms_since(request_started);
        let answer = readiness_within_budget(
            controller,
            principal,
            &parsed.identity,
            VOICE_READINESS_SERVER_BUDGET,
        )
        .await;
        log_voice_readiness(&parsed.identity, pre_check_ms, &answer);
        return match answer.outcome {
            ReadinessOutcome::Answered(Ok(report)) => {
                response_value(id, Some(report.to_wire(&parsed.identity)), None)
            }
            ReadinessOutcome::Answered(Err(failure)) => error(failure),
            ReadinessOutcome::TimedOut => error(VoiceError::ReadinessTimedOut),
        };
    }
    if request.method == VOICE_CONTEXT_STATUS_METHOD {
        let parsed: VoiceContextStatusRequest = match serde_json::from_value(request.params) {
            Ok(parsed) => parsed,
            Err(_) => return error(VoiceError::InvalidRequest),
        };
        let Some(controller) = controller else {
            return error(VoiceError::Unavailable);
        };
        return match controller.context_status(principal, parsed).await {
            Ok(status) => match serde_json::to_value(status) {
                Ok(value) => response_value(id, Some(value), None),
                Err(_) => error(VoiceError::ContextReadFailed),
            },
            Err(failure) => error(failure),
        };
    }
    if request.method == VOICE_CAPTIONS_METHOD {
        let parsed: VoiceCaptionsRequest = match serde_json::from_value(request.params) {
            Ok(parsed) => parsed,
            Err(_) => return error(VoiceError::InvalidRequest),
        };
        let Some(controller) = controller else {
            return error(VoiceError::Unavailable);
        };
        return match controller.captions(principal, parsed).await {
            Ok(captions) => match serde_json::to_value(captions) {
                Ok(value) => response_value(id, Some(value), None),
                Err(_) => error(VoiceError::HostFailed),
            },
            Err(failure) => error(failure),
        };
    }
    if crate::console_voice::is_channel_method(&request.method) {
        let Some(controller) = controller else {
            return error(VoiceError::Unavailable);
        };
        return match controller
            .dispatch_channel(principal, &request.method, request.params)
            .await
        {
            Ok(value) => response_value(id, Some(value), None),
            Err(failure) => error(failure),
        };
    }
    let answer: Option<VoiceAnswerReceived> = if request.method == VOICE_ANSWER_RECEIVED_METHOD {
        match serde_json::from_value(request.params.clone()) {
            Ok(parsed) => Some(parsed),
            Err(_) => return error(VoiceError::InvalidRequest),
        }
    } else {
        None
    };
    let activity: Option<VoiceActivity> = if request.method == VOICE_ACTIVITY_METHOD {
        match serde_json::from_value(request.params.clone()) {
            Ok(parsed) => Some(parsed),
            Err(_) => return error(VoiceError::InvalidRequest),
        }
    } else {
        None
    };
    let parsed: VoiceRequest = if let Some(answer) = &answer {
        VoiceRequest {
            identity: answer.identity.clone(),
            request_id: answer.request_id.clone(),
        }
    } else if let Some(activity) = &activity {
        VoiceRequest {
            identity: activity.identity.clone(),
            request_id: activity.request_id.clone(),
        }
    } else {
        match serde_json::from_value(request.params.clone()) {
            Ok(parsed) => parsed,
            Err(_) => return error(VoiceError::InvalidRequest),
        }
    };
    // Teardown retains the authenticated request owner after view/send/auth
    // readiness revocation. It never promotes a missing principal to stdio.
    let Some(controller) = controller else {
        return error(VoiceError::Unavailable);
    };
    match request.method.as_str() {
        VOICE_OPEN_METHOD => match controller
            .open_while_authenticated(
                principal,
                parsed,
                auth.verification
                    .clone()
                    .map(crate::http_sse::StreamAuthentication::new),
            )
            .await
        {
            Ok(pending) => match serde_json::to_value(pending) {
                Ok(value) => response_value(id, Some(value), None),
                Err(_) => error(VoiceError::HostFailed),
            },
            Err(failure) => error(failure),
        },
        VOICE_CLOSE_METHOD => match controller.close(principal, parsed).await {
            Ok(()) => response_value(id, Some(json!({ "phase": "closed" })), None),
            Err(failure) => error(failure),
        },
        VOICE_ANSWER_RECEIVED_METHOD => {
            let Some(answer) = answer else {
                return error(VoiceError::InvalidRequest);
            };
            match controller
                .answer_received(principal, parsed, &answer.channel_id)
                .await
            {
                Ok(()) => response_value(id, Some(json!({"accepted":true})), None),
                Err(failure) => error(failure),
            }
        }
        VOICE_REPLACEMENT_METHOD => {
            match controller.replacement_required(principal, parsed).await {
                Ok(value) => response_value(id, Some(value), None),
                Err(failure) => error(failure),
            }
        }
        VOICE_ACTIVITY_METHOD => {
            let Some(activity) = activity else {
                return error(VoiceError::InvalidRequest);
            };
            match controller.note_activity(principal, activity).await {
                Ok(()) => response_value(id, Some(json!({"accepted":true})), None),
                Err(failure) => error(failure),
            }
        }
        _ => error(VoiceError::InvalidRequest),
    }
}

fn decorate_console_job_projection(
    mut response: Value,
    method: &str,
    projection_slot: Option<&Arc<std::sync::RwLock<Option<Value>>>>,
) -> Value {
    let projection = projection_slot.and_then(|slot| {
        slot.read()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .clone()
    });
    let Some(projection) = projection else {
        return response;
    };
    match method {
        "meta/status" | "meta/capabilities" => {
            response["result"]["detached_jobs"] = projection
                .get("detached_jobs")
                .cloned()
                .unwrap_or(Value::Null);
        }
        "meta/member_status" => {
            if let Some(session_id) = response["result"]["current_session_id"].as_str()
                && let Some(session_jobs) = projection
                    .get("by_session")
                    .and_then(|by_session| by_session.get(session_id))
            {
                response["result"]["detached_jobs"] = session_jobs.clone();
                response["result"]["awaiting_detached"] = session_jobs
                    .get("awaiting_detached")
                    .cloned()
                    .unwrap_or(Value::Bool(false));
            }
        }
        _ => {}
    }
    response
}

#[derive(Debug, serde::Deserialize)]
struct ConsoleTimelineHttpQuery {
    #[serde(default)]
    identity: Option<String>,
    #[serde(default)]
    conversation_id: Option<String>,
    #[serde(default)]
    after: Option<String>,
    #[serde(default)]
    before: Option<String>,
    #[serde(default)]
    mode: Option<ConsoleTimelineMode>,
    #[serde(default)]
    limit: Option<usize>,
}

async fn console_identities_handler(
    State(state): State<ConsoleJsonState>,
    headers: HeaderMap,
    uri: Uri,
) -> impl IntoResponse {
    let Some(auth_context) = console_request_auth_context(&state, &headers, &uri) else {
        return console_json_error(
            StatusCode::UNAUTHORIZED,
            "unauthorized",
            "console identities require a valid auth token",
        );
    };
    let Some(aggregator) = &state.console_aggregator else {
        return console_json_error(
            StatusCode::NOT_FOUND,
            "unavailable",
            "console aggregator unavailable",
        );
    };
    let aggregator = aggregator.clone();
    match Box::pin(aggregator.list_identities()).await {
        Ok(mut identities) => {
            retain_visible_identity_records(&mut identities, auth_context.access_view.as_ref());
            (
                StatusCode::OK,
                Json::<Value>(json!({ "identities": identities })),
            )
                .into_response()
        }
        Err(err) => {
            tracing::warn!(target: "meta::console", error = %err, "console identities request failed");
            console_json_error(
                StatusCode::INTERNAL_SERVER_ERROR,
                "internal_error",
                "console identities unavailable",
            )
        }
    }
}

async fn console_timeline_handler(
    State(state): State<ConsoleJsonState>,
    headers: HeaderMap,
    uri: Uri,
    Query(query): Query<ConsoleTimelineHttpQuery>,
) -> impl IntoResponse {
    let Some(auth_context) = console_request_auth_context(&state, &headers, &uri) else {
        return console_json_error(
            StatusCode::UNAUTHORIZED,
            "unauthorized",
            "console timeline requires a valid auth token",
        );
    };
    let Some(aggregator) = &state.console_aggregator else {
        return console_json_error(
            StatusCode::NOT_FOUND,
            "unavailable",
            "console aggregator unavailable",
        );
    };
    // Prime the attribute cache from the live roster so label/role rules
    // resolve when filtering frames by `agent.view` — the timeline REST
    // surface must not depend on a prior `/console/experience` call.
    if let Some(runtime) = &state.runtime
        && let Some(controller) = state.access.as_ref().filter(|c| c.enabled())
    {
        prime_access_cache_from_runtime(runtime, controller).await;
    }
    let timeline_query = timeline_query_from_http(query, None);
    let decider = timeline_frame_decider(auth_context.access_view.as_ref());
    let frame_filter = decider.as_ref().map(timeline_frame_filter);
    match Box::pin(aggregator.query_timeline_windowed_for(timeline_query, frame_filter.as_deref()))
        .await
    {
        Ok(page) => (
            StatusCode::OK,
            Json::<Value>(serde_json::to_value(page).unwrap_or_else(|_| json!({ "frames": [] }))),
        )
            .into_response(),
        Err(err) => console_timeline_query_error_response(err),
    }
}

async fn console_send_handler(
    State(state): State<ConsoleJsonState>,
    headers: HeaderMap,
    uri: Uri,
    Json(request): Json<ConsoleSendRequest>,
) -> impl IntoResponse {
    let Some(auth_context) = console_request_auth_context(&state, &headers, &uri) else {
        return console_json_error(
            StatusCode::UNAUTHORIZED,
            "unauthorized",
            "console send requires a valid auth token",
        );
    };
    // A candidate launch admits no member input: 409 `candidate_launch`,
    // the REST form of the RPC surfaces' `-32047` refusal.
    if state
        .runtime
        .as_ref()
        .is_some_and(|runtime| !runtime.speaks_for_composition())
    {
        return console_json_error(
            StatusCode::CONFLICT,
            "candidate_launch",
            "this gateway is a candidate launch and admits no member input; its members' \
             work belongs to the authoritative launch",
        );
    }
    if let Err(refusal) = console_send_gate(
        &state.decisions,
        state.runtime.as_ref(),
        state.access.as_ref(),
        auth_context.access_view.as_ref(),
        request.identity.as_str(),
    )
    .await
    {
        return refusal.into_response();
    }
    // §16 Q1 provisional operator keying: an authenticated principal
    // addressing this identity IS the active operator for its turns.
    // Unauthenticated consoles (no subject) note nothing — operator-scope
    // recall stays inert without a real principal.
    if let Some(resolver) = state.operator_resolver.as_ref()
        && let Some(subject) = auth_context
            .access_view
            .as_ref()
            .and_then(|view| view.subject())
    {
        resolver.note_interaction(request.identity.as_str(), subject);
    }
    let Some(aggregator) = &state.console_aggregator else {
        return console_json_error(
            StatusCode::NOT_FOUND,
            "unavailable",
            "console aggregator unavailable",
        );
    };
    let governance = ConsoleSendGovernance::for_request(&state, &auth_context);
    if let Some(identity_runtime) = &state.identity_runtime {
        return match Box::pin(console_send_governed_with_identity_first_fallback(
            aggregator,
            Arc::clone(identity_runtime.runtime()),
            state.console_events.as_ref(),
            request,
            &governance,
        ))
        .await
        {
            Ok(accepted) => (
                StatusCode::OK,
                Json::<Value>(
                    serde_json::to_value(accepted).unwrap_or_else(|_| json!({ "accepted": true })),
                ),
            )
                .into_response(),
            Err(err) => console_send_error_response(err),
        };
    }
    if let Err(err) = governance.refuse_ungoverned_delivery(request.identity.as_str()) {
        return console_send_error_response(err);
    }
    match Box::pin(aggregator.send_scoped(request, &governance.scope)).await {
        Ok(accepted) => (
            StatusCode::OK,
            Json::<Value>(
                serde_json::to_value(accepted).unwrap_or_else(|_| json!({ "accepted": true })),
            ),
        )
            .into_response(),
        Err(err) => console_send_error_response(err),
    }
}

/// `POST /console/send/recover`: the REST twin of `meta/console/recover_send`.
/// It runs the same gate as `/console/send`, and the caller is the
/// authenticated principal, never a parameter.
async fn console_send_recover_handler(
    State(state): State<ConsoleJsonState>,
    headers: HeaderMap,
    uri: Uri,
    Json(params): Json<Value>,
) -> impl IntoResponse {
    let Some(auth_context) = console_request_auth_context(&state, &headers, &uri) else {
        return console_json_error(
            StatusCode::UNAUTHORIZED,
            "unauthorized",
            "console send recovery requires a valid auth token",
        );
    };
    // A candidate launch settles no console send: a recovery marks the send
    // delivered in the Console store the authoritative launch reads. 409
    // `candidate_launch`, as `POST /console/send` answers.
    if state
        .runtime
        .as_ref()
        .is_some_and(|runtime| !runtime.speaks_for_composition())
    {
        return console_json_error(
            StatusCode::CONFLICT,
            "candidate_launch",
            "this gateway is a candidate launch and settles no console send; recover it on \
             the authoritative launch",
        );
    }
    let identity = params
        .get("identity")
        .and_then(Value::as_str)
        .unwrap_or_default()
        .to_string();
    if let Err(refusal) = console_send_gate(
        &state.decisions,
        state.runtime.as_ref(),
        state.access.as_ref(),
        auth_context.access_view.as_ref(),
        identity.as_str(),
    )
    .await
    {
        return refusal.into_response();
    }
    let Some(aggregator) = &state.console_aggregator else {
        return console_json_error(
            StatusCode::NOT_FOUND,
            "unavailable",
            "console aggregator unavailable",
        );
    };
    let identity_runtime = state
        .identity_runtime
        .as_ref()
        .map(|identity_runtime| Arc::clone(identity_runtime.runtime()));
    match Box::pin(recover_console_send(
        aggregator,
        identity_runtime.as_ref(),
        &params,
        &auth_context.send_scope(),
    ))
    .await
    {
        Ok(recovery) => (
            StatusCode::OK,
            Json::<Value>(serde_json::to_value(recovery).unwrap_or(Value::Null)),
        )
            .into_response(),
        Err(RecoverSendFailure::InvalidParams(message)) => {
            console_json_error(StatusCode::BAD_REQUEST, "invalid_request", &message)
        }
        Err(RecoverSendFailure::NotFound) => console_json_error(
            StatusCode::NOT_FOUND,
            CONSOLE_SEND_NOT_FOUND_KIND,
            CONSOLE_SEND_NOT_FOUND_MESSAGE,
        ),
        Err(RecoverSendFailure::Send(err)) => console_send_error_response(err),
    }
}

/// Typed kind of a recovery that names no send of the caller's. The answer is
/// the same for a key nobody used and for a key another caller used.
const CONSOLE_SEND_NOT_FOUND_KIND: &str = "send_not_found";
const CONSOLE_SEND_NOT_FOUND_MESSAGE: &str = "no console send of yours has this idempotency key";

/// `meta/console/recover_send` parameters: the send's own identity, origin
/// and idempotency key. Nothing else is accepted, so no interaction or frame
/// id can be offered as a lookup key.
#[derive(Debug, serde::Deserialize)]
#[serde(deny_unknown_fields)]
struct ConsoleSendRecoverParams {
    identity: String,
    origin: String,
    idempotency_key: String,
}

#[derive(Debug)]
enum RecoverSendFailure {
    InvalidParams(String),
    NotFound,
    Send(ConsoleSendError),
}

/// Recover the caller's own console send: its acceptance as it is now and
/// what the runtime holds for it, settling it from admission evidence when
/// the evidence shows it admitted. Nothing is dispatched. The send is found
/// only under the caller's `scope`.
async fn recover_console_send(
    aggregator: &MetaConsoleAggregator,
    identity_runtime: Option<&Arc<crate::identity_first::IdentityRuntime>>,
    params: &Value,
    scope: &ConsoleSendScope,
) -> Result<ConsoleSendRecovery, RecoverSendFailure> {
    let params: ConsoleSendRecoverParams =
        serde_json::from_value(params.clone()).map_err(|err| {
            RecoverSendFailure::InvalidParams(format!("invalid recover params: {err}"))
        })?;
    for (field, value) in [
        ("identity", params.identity.as_str()),
        ("origin", params.origin.as_str()),
        ("idempotency_key", params.idempotency_key.as_str()),
    ] {
        if value.trim().is_empty() {
            return Err(RecoverSendFailure::InvalidParams(format!(
                "{field} must be non-empty"
            )));
        }
    }
    let identities = Box::pin(console_send_identity_candidates(
        aggregator,
        identity_runtime,
        &params.identity,
    ))
    .await;
    match Box::pin(aggregator.recover_send(
        &identities,
        &params.origin,
        &params.idempotency_key,
        scope,
    ))
    .await
    {
        Ok(Some(recovery)) => Ok(recovery),
        Ok(None) => Err(RecoverSendFailure::NotFound),
        Err(err) => Err(RecoverSendFailure::Send(err)),
    }
}

/// The identities a console send to `identity` can be recorded under: as
/// addressed, and the canonical durable identity an alias resolved to (an
/// identity-first send records the canonical one).
async fn console_send_identity_candidates(
    aggregator: &MetaConsoleAggregator,
    identity_runtime: Option<&Arc<crate::identity_first::IdentityRuntime>>,
    identity: &str,
) -> Vec<String> {
    let mut candidates = vec![identity.to_string()];
    let Some(identity_runtime) = identity_runtime else {
        return candidates;
    };
    let addressed_directly = match crate::identity_first::AgentIdentity::parse(identity) {
        Ok(parsed) => identity_runtime.status(&parsed).await.is_ok(),
        Err(_) => false,
    };
    if !addressed_directly
        && let Some(canonical) =
            Box::pin(resolve_console_send_identity_alias(aggregator, identity)).await
        && canonical != identity
    {
        candidates.push(canonical);
    }
    candidates
}

fn console_send_recovery_rpc_response(
    response_id: Value,
    recovered: Result<ConsoleSendRecovery, RecoverSendFailure>,
) -> Value {
    match recovered {
        Ok(recovery) => response_value(
            response_id,
            Some(serde_json::to_value(recovery).unwrap_or(Value::Null)),
            None,
        ),
        Err(RecoverSendFailure::InvalidParams(message)) => invalid_params(response_id, message),
        Err(RecoverSendFailure::NotFound) => response_value(
            response_id,
            None,
            Some(JsonRpcError {
                code: -32001,
                message: CONSOLE_SEND_NOT_FOUND_MESSAGE.to_string(),
                data: Some(json!({ "kind": CONSOLE_SEND_NOT_FOUND_KIND })),
            }),
        ),
        Err(RecoverSendFailure::Send(err)) => {
            response_value(response_id, None, Some(console_send_json_rpc_error(err)))
        }
    }
}

/// Why the Console's stock send gate refuses a send. Each is exactly the
/// refusal `/console/send` answers with (see [`Self::status`],
/// [`Self::code`] and [`Self::message`]).
#[derive(Debug, Clone, PartialEq, Eq)]
#[non_exhaustive]
pub enum ConsoleSendGateRefusal {
    /// The Console is read-only.
    ReadOnly,
    /// The target is not a valid public member alias; the detail is the
    /// validation message.
    InvalidTarget(String),
    /// The Console's access policy does not let the caller send to the
    /// target (`agent.send`).
    AccessDenied,
}

impl ConsoleSendGateRefusal {
    /// The HTTP status `/console/send` answers this refusal with.
    pub fn status(&self) -> StatusCode {
        match self {
            Self::ReadOnly | Self::AccessDenied => StatusCode::FORBIDDEN,
            Self::InvalidTarget(_) => StatusCode::BAD_REQUEST,
        }
    }

    /// The wire `error` code `/console/send` answers this refusal with.
    pub fn code(&self) -> &'static str {
        match self {
            Self::ReadOnly => "read_only",
            Self::InvalidTarget(_) => "invalid_request",
            Self::AccessDenied => "access_denied",
        }
    }

    /// The wire `message` `/console/send` answers this refusal with.
    pub fn message(&self) -> &str {
        match self {
            Self::ReadOnly => "console is read-only",
            Self::InvalidTarget(message) => message,
            Self::AccessDenied => "you are not allowed to send to this agent",
        }
    }

    fn into_response(self) -> axum::response::Response {
        console_json_error(self.status(), self.code(), self.message())
    }
}

/// The Console's stock send gate, the one implementation `/console/send` and
/// [`ConsoleSendPrecheck`] run: the Console is writable, the target is a
/// valid public member alias, and the caller's access view allows
/// `agent.send` to it, decided after the attribute cache is primed from the
/// live roster.
async fn console_send_gate(
    decisions: &RuntimeDecisionState,
    runtime: Option<&MobRuntime>,
    access: Option<&AccessController>,
    access_view: Option<&AccessView>,
    identity: &str,
) -> Result<(), ConsoleSendGateRefusal> {
    if decisions.console.read_only {
        return Err(ConsoleSendGateRefusal::ReadOnly);
    }
    crate::member_comms_id::validate_public_member_alias("identity", identity)
        .map_err(ConsoleSendGateRefusal::InvalidTarget)?;
    // Prime the attribute cache from the live roster BEFORE the `agent.send`
    // decision: role/label-scoped rules resolve through the cache, and on a
    // cold cache the decision degrades to a bare-identity resource - a deny
    // rule scoped by `roles`/`match_labels` would not match, so a scripted
    // caller hitting `/console/send` as its first request could reach a
    // member the rule was meant to exclude (fail-closed requires the
    // attributes to be present when the rule is evaluated).
    if let Some(runtime) = runtime
        && let Some(controller) = access.filter(|c| c.enabled())
    {
        prime_access_cache_from_runtime(runtime, controller).await;
    }
    if let Some(view) = access_view
        && view.enforced()
        && !view.allows_agent(ACTION_AGENT_SEND, identity)
    {
        return Err(ConsoleSendGateRefusal::AccessDenied);
    }
    Ok(())
}

/// The Console's stock send gate for a host that prepares a Console send
/// before the human sends it (for example a host route reviewing the
/// original): the same gate `/console/send` runs, with the same Console
/// decisions, live roster and access controller
/// ([`crate::UnifiedRuntime::console_send_precheck`]). Only the gate: it
/// resolves no identity, reserves nothing, admits nothing and notes no
/// operator. A pass is advisory, never an authorization the send relies on:
/// the send runs the gate again, and a governed send's binder rechecks the
/// human and access at bind.
#[derive(Clone)]
pub struct ConsoleSendPrecheck {
    decisions: RuntimeDecisionState,
    runtime: Option<MobRuntime>,
    access: Option<AccessController>,
}

impl std::fmt::Debug for ConsoleSendPrecheck {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("ConsoleSendPrecheck")
            .field("read_only", &self.decisions.console.read_only)
            .field("access_controller", &self.access.is_some())
            .finish()
    }
}

impl ConsoleSendPrecheck {
    pub(crate) fn new(
        decisions: RuntimeDecisionState,
        runtime: Option<MobRuntime>,
        access: Option<AccessController>,
    ) -> Self {
        Self {
            decisions,
            runtime,
            access,
        }
    }

    /// The stock send gate for `viewer` (resolved by the Console's own
    /// [`ConsoleViewerResolver`]) sending to `identity`, as `/console/send`
    /// would run it now.
    pub async fn check(
        &self,
        viewer: &ConsoleViewerContext,
        identity: &str,
    ) -> Result<(), ConsoleSendGateRefusal> {
        console_send_gate(
            &self.decisions,
            self.runtime.as_ref(),
            self.access.as_ref(),
            viewer.access_view.as_ref(),
            identity,
        )
        .await
    }
}

/// The trusted host's governance of one Console send and the verified human
/// who sent it.
#[derive(Default)]
pub(crate) struct ConsoleSendGovernance {
    pub(crate) ingress: Option<Arc<dyn crate::console_governed_ingress::ConsoleGovernedIngress>>,
    pub(crate) human: Option<crate::runtime::AuthenticatedConsoleHuman>,
    /// Whose send this is: the dedupe scope of its idempotency key.
    pub(crate) scope: ConsoleSendScope,
    /// The runtime's canonical composition: its machine has a host's native
    /// work authorization owner installed, so every member admits only
    /// governed input, whether or not a Console ingress is installed.
    pub(crate) runtime_governed: bool,
    /// The Console's access controller, rechecked with the human when the
    /// host binds.
    pub(crate) access: Option<AccessController>,
}

impl ConsoleSendGovernance {
    fn for_request(state: &ConsoleJsonState, auth_context: &ConsoleHttpAuthContext) -> Self {
        Self {
            ingress: state.governed_ingress.current(),
            human: auth_context.human.clone(),
            scope: auth_context.send_scope(),
            runtime_governed: state
                .runtime
                .as_ref()
                .is_some_and(MobRuntime::native_work_governed),
            access: state.access.clone(),
        }
    }

    /// Whether a send to `identity` must be governed: the runtime's canonical
    /// composition says so, or the installed host governs it. An installed
    /// host's `governs` adds governance; it never removes the runtime's.
    fn governed(&self, identity: &crate::identity_first::AgentIdentity) -> bool {
        self.runtime_governed
            || self
                .ingress
                .as_ref()
                .is_some_and(|ingress| ingress.governs(identity))
    }

    /// The host's binder for a send to `identity` (the canonical identity the
    /// send resolved to) when it must be governed, refusing a caller who is
    /// not a verified Console human and a governed target with no installed
    /// host; `None` when the send is not governed. The host builds it with
    /// the send's own context
    /// ([`ConsoleGovernedIngress::binder_for_send`](crate::console_governed_ingress::ConsoleGovernedIngress::binder_for_send)).
    /// The binder re-verifies the human (and the Console's access to
    /// `identity`) when it binds, after every await between acceptance and
    /// binding.
    fn binder_for(
        &self,
        identity: &crate::identity_first::AgentIdentity,
        send: &crate::console_governed_ingress::ConsoleSendContext,
    ) -> Result<Option<Arc<dyn crate::identity_first::GovernedInputBinder>>, ConsoleSendError> {
        if !self.governed(identity) {
            return Ok(None);
        }
        let ingress = self.ingress.as_ref().ok_or_else(|| {
            ConsoleSendError::GovernedRefused(format!(
                "{identity} admits only governed input and no Console ingress is installed"
            ))
        })?;
        let human = self
            .human
            .as_ref()
            .ok_or_else(|| ConsoleSendError::UnqualifiedPrincipal(identity.to_string()))?;
        let binder = ingress
            .binder_for_send(identity, human, send)
            .map_err(ConsoleSendError::GovernedRefused)?;
        Ok(Some(Arc::new(CurrentHumanBinder {
            inner: binder,
            human: human.clone(),
            identity: identity.clone(),
            access: self.access.clone(),
        })))
    }

    /// Refuse every delivery outside identity-first admission (the member
    /// send path, which resolves its own aliases and could carry no binding)
    /// once Console sends can be governed: the decision cannot be checked
    /// there, so it fails closed.
    fn refuse_ungoverned_delivery(&self, identity: &str) -> Result<(), ConsoleSendError> {
        if self.ingress.is_none() && !self.runtime_governed {
            return Ok(());
        }
        Err(ConsoleSendError::GovernedRefused(format!(
            "Console sends are governed and {identity} has no identity-first admission"
        )))
    }
}

/// The host's binder behind a re-verification of the Console human: at the
/// asynchronous bind entry the human must still be current (the retained
/// token still verifies under the Console's decisions and names the same
/// issuer and subject) and the Console's current access policy must still let
/// that principal send to the identity. Otherwise nothing reaches the host's
/// binder and nothing is submitted.
struct CurrentHumanBinder {
    inner: Arc<dyn crate::identity_first::GovernedInputBinder>,
    human: crate::runtime::AuthenticatedConsoleHuman,
    identity: crate::identity_first::AgentIdentity,
    access: Option<AccessController>,
}

#[async_trait::async_trait]
impl crate::identity_first::GovernedInputBinder for CurrentHumanBinder {
    async fn bind(
        &self,
        context: &crate::identity_first::GovernedBindContext,
        input: meerkat_runtime::Input,
    ) -> Result<crate::identity_first::BoundGovernedInput, String> {
        human_still_sends(&self.human, self.access.as_ref(), &self.identity)?;
        let mut bound = self.inner.bind(context, input).await?;
        // Checked again at the final protected entry, after every await
        // between here and native admission, ahead of the host's own fence.
        bound.entry_fence = Some(Arc::new(CurrentHumanFence {
            human: self.human.clone(),
            identity: self.identity.clone(),
            access: self.access.clone(),
            inner: bound.entry_fence.take(),
        }));
        Ok(bound)
    }

    fn retain_unresolved(
        &self,
        settlement: Box<dyn crate::identity_first::GovernedSettlement>,
        detail: &str,
    ) {
        self.inner.retain_unresolved(settlement, detail);
    }
}

/// The Console human is still authenticated (its retained token still
/// verifies with the same issuer, subject and login association) and the
/// Console's live access policy still lets it send to `identity`.
fn human_still_sends(
    human: &crate::runtime::AuthenticatedConsoleHuman,
    access: Option<&AccessController>,
    identity: &crate::identity_first::AgentIdentity,
) -> Result<(), String> {
    let access_subject = human.current().map_err(|error| error.to_string())?;
    if let Some(controller) = access.filter(|c| c.enabled()) {
        let view = controller.view_for_subject(Some(access_subject.as_str()));
        if view.enforced() && !view.allows_agent(ACTION_AGENT_SEND, identity.as_str()) {
            return Err("the Console human may no longer send to this agent".to_string());
        }
    }
    Ok(())
}

/// The final-entry fence of a governed Console send: the human's
/// authentication and access are re-checked synchronously at the entry, then
/// the host's own fence (if any) is entered. Both checks are strictly local:
/// [`AuthenticatedConsoleHuman::current`](crate::runtime::AuthenticatedConsoleHuman::current)
/// re-verifies the retained token against the retained verifier snapshot
/// (its decisions and JWKS, with no fetch, network or await), and the access
/// read takes the controller's in-memory configuration snapshot.
struct CurrentHumanFence {
    human: crate::runtime::AuthenticatedConsoleHuman,
    identity: crate::identity_first::AgentIdentity,
    access: Option<AccessController>,
    inner: Option<Arc<dyn crate::identity_first::GovernedEntryFence>>,
}

/// A reservation with no host fence behind it: nothing to report to.
struct UnfencedPermit;

impl crate::identity_first::GovernedEntryPermit for UnfencedPermit {
    fn finish(self: Box<Self>, _outcome: crate::identity_first::GovernedEntryOutcome) {}
}

impl crate::identity_first::GovernedEntryFence for CurrentHumanFence {
    fn enter(
        &self,
    ) -> Result<
        Box<dyn crate::identity_first::GovernedEntryPermit>,
        crate::identity_first::GovernedEntryRefusal,
    > {
        human_still_sends(&self.human, self.access.as_ref(), &self.identity)
            .map_err(crate::identity_first::GovernedEntryRefusal::NotAuthorized)?;
        match &self.inner {
            Some(fence) => fence.enter(),
            None => Ok(Box::new(UnfencedPermit)),
        }
    }
}

#[cfg(test)]
async fn console_send_with_identity_first_fallback(
    aggregator: &MetaConsoleAggregator,
    identity_runtime: Arc<crate::identity_first::IdentityRuntime>,
    console_events: Option<&ConsoleEventStore>,
    request: ConsoleSendRequest,
) -> Result<crate::console_aggregator::ConsoleInteractionAccepted, ConsoleSendError> {
    console_send_governed_with_identity_first_fallback(
        aggregator,
        identity_runtime,
        console_events,
        request,
        &crate::http_console::ConsoleSendGovernance::default(),
    )
    .await
}

async fn console_send_governed_with_identity_first_fallback(
    aggregator: &MetaConsoleAggregator,
    identity_runtime: Arc<crate::identity_first::IdentityRuntime>,
    console_events: Option<&ConsoleEventStore>,
    request: ConsoleSendRequest,
    governance: &ConsoleSendGovernance,
) -> Result<crate::console_aggregator::ConsoleInteractionAccepted, ConsoleSendError> {
    let member_send_request = request.clone();
    match Box::pin(console_send_identity_first_governed(
        aggregator,
        identity_runtime,
        console_events,
        request,
        governance,
    ))
    .await
    {
        Err(ConsoleSendError::UnknownIdentity(_)) => {
            governance.refuse_ungoverned_delivery(member_send_request.identity.as_str())?;
            Box::pin(aggregator.send_scoped(member_send_request, &governance.scope)).await
        }
        result => result,
    }
}

