    #[tokio::test]
    async fn authenticated_gating_request_rechecks_revoked_role_before_decision()
    -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
        use crate::access::{AccessApprover, AccessControlConfig, AccessGroup, AccessRule};
        use crate::runtime::{GatingResolutionNotice, GatingResolutionObserver};

        const BOB: &str = "bob@example.test";
        const CAROL: &str = "carol@example.test";
        const ROLE: &str = "role:release-manager";
        const ISSUER: &str = "https://trusted.meta.localhost";

        #[derive(Default)]
        struct Collector(Mutex<Vec<GatingResolutionNotice>>);

        impl GatingResolutionObserver for Collector {
            fn on_gating_resolution(&self, notice: &GatingResolutionNotice) {
                self.0.lock().expect("observer").push(notice.clone());
            }
        }

        async fn decide(
            runtime: &MobRuntime,
            module: &Arc<tokio::sync::Mutex<crate::MetaRuntimeHandle>>,
            access: &AccessController,
            auth: &super::ConsoleHttpAuthContext,
            pending: &str,
        ) -> Value {
            Box::pin(handle_console_runtime_rpc_with_visibility(
                runtime,
                Some(module.clone()),
                None,
                None,
                None,
                None,
                None,
                None,
                None,
                &AllowAllConsoleVisibilityPolicy,
                rpc_request_with_params(
                    "meta/gating/decide",
                    json!({
                        "pending_id": pending,
                        "approver_id": CAROL,
                        "held_approver_ids": [ROLE],
                        "decision": "approve",
                    }),
                ),
                true,
                false,
                auth.principal.as_deref(),
                Some(access),
                auth.access_view.as_ref(),
                None,
                None,
                None,
                None,
                None,
                &crate::http_console::ConsoleSendGovernance::default(),
                &crate::topology_control::TopologyApplyScope::Anonymous,
            ))
            .await
        }

        let access = AccessController::new(AccessControlConfig {
            enabled: true,
            admins: vec!["root@example.test".to_string()],
            groups: BTreeMap::from([(
                "release".to_string(),
                AccessGroup {
                    members: vec![BOB.to_string(), CAROL.to_string()],
                    ..AccessGroup::default()
                },
            )]),
            approvers: BTreeMap::from([(
                ROLE.to_string(),
                AccessApprover {
                    groups: vec!["release".to_string()],
                    ..AccessApprover::default()
                },
            )]),
            // Removing the role must not also remove gating.decide: this
            // isolates current approver eligibility from the general grant.
            rules: vec![AccessRule {
                id: "gate-deciders".to_string(),
                subjects: vec![BOB.to_string(), CAROL.to_string()],
                actions: vec![crate::access::ACTION_GATING_DECIDE.to_string()],
                ..AccessRule::default()
            }],
        })?;
        // Same development issuer/key and signed request shape as the real
        // HTTP access-control fixtures; no request field supplies identity.
        let decisions = crate::build_runtime_decision_state(crate::RuntimeDecisionInputs {
            bigquery: crate::BigQueryNaming {
                dataset: "access_dataset".to_string(),
                table: "access_table".to_string(),
            },
            trusted_meta_toml: "[[modules]]\nid = \"router\"\ncommand = \"router-bin\"\nargs = []\nrestart_policy = \"always\"\n".to_string(),
            auth: crate::AuthPolicy {
                default_provider: crate::AuthProvider::GoogleOAuth,
                email_allowlist: vec![BOB.to_string(), CAROL.to_string()],
            },
            trusted_oidc: crate::TrustedOidcRuntimeConfig {
                discovery_json: json!({
                    "issuer": ISSUER,
                    "jwks_uri": format!("{ISSUER}/.well-known/jwks.json"),
                }).to_string(),
                jwks_json: r#"{"keys":[{"kid":"kid-current","kty":"oct","alg":"HS256","k":"cGhhc2U3LXRydXN0ZWQtY3VycmVudC1zZWNyZXQ"}]}"#.to_string(),
                audience: "meerkat-console".to_string(),
                require_verified_email: true,
            },
            console: crate::ConsolePolicy {
                require_app_auth: true,
                read_only: false,
                ..crate::ConsolePolicy::default()
            },
            ops: crate::RuntimeOpsPolicy::default(),
            release_metadata_json: include_str!("../assets/release-targets.json").to_string(),
        })?;
        let state = super::ConsoleJsonState {
            decisions,
            session_fences: crate::auth::session_fence::ConsoleSessionFences::detached(),
            runtime: None,
            module_runtime: None,
            contact_directory: None,
            event_log: None,
            gateway_peer_keys: None,
            identity_runtime: None,
            console_events: None,
            console_aggregator: None,
            mob_events: None,
            metadata_table: None,
            visibility_policy: Arc::new(AllowAllConsoleVisibilityPolicy),
            snapshot_read_model: ConsoleSnapshotReadModel::default(),
            access: Some(access.clone()),
            memory_panel: None,
            operator_resolver: None,
            identity_roster: None,
            workgraph: None,
            topology: None,
            job_health_projection: None,
            governed_ingress: Default::default(),
            mob_announcements: Default::default(),
        };
        let authenticate = |subject: &str| {
            let mut header = jsonwebtoken::Header::new(jsonwebtoken::Algorithm::HS256);
            header.kid = Some("kid-current".to_string());
            let token = jsonwebtoken::encode(
                &header,
                &json!({
                    "iss": ISSUER,
                    "aud": "meerkat-console",
                    "sub": subject,
                    "email": subject,
                    "email_verified": true,
                    "provider": "google_oauth",
                    "exp": chrono::Utc::now().timestamp() + 300,
                }),
                &jsonwebtoken::EncodingKey::from_secret(b"phase7-trusted-current-secret"),
            )
            .expect("signed fixture JWT");
            let mut headers = axum::http::HeaderMap::new();
            headers.insert(
                axum::http::header::AUTHORIZATION,
                format!("Bearer {token}").parse().expect("bearer header"),
            );
            super::console_request_auth_context(
                &state,
                &headers,
                &axum::http::Uri::from_static("/console/rpc"),
            )
            .expect("actual console JWT authenticator accepts the fixture")
        };

        let bob = authenticate(BOB);
        assert_eq!(bob.principal.as_deref(), Some(BOB));
        assert_eq!(
            bob.access_view
                .as_ref()
                .expect("access view")
                .held_approver_ids(),
            std::collections::BTreeSet::from([ROLE.to_string()]),
        );
        let mut owner = crate::start_meta_runtime(
            crate::MetaConfig {
                modules: vec![],
                discovery: crate::DiscoverySpec {
                    namespace: "gating-revocation".to_string(),
                    modules: vec![],
                },
                pre_spawn: vec![],
            },
            vec![],
            Duration::from_secs(1),
        )?;
        let evaluated = owner.evaluate_gating_action(serde_json::from_value(json!({
            "action": "Publish release",
            "actor_id": "agent:writer",
            "risk_tier": "r3",
            "requested_approver": ROLE,
            "approval_timeout_ms": 600_000,
        }))?);
        let pending = evaluated.pending_id.expect("real R3 pending entry");
        let collector = Arc::new(Collector::default());
        owner.register_gating_resolution_observer(collector.clone());
        let before = owner.gating_state_snapshot();
        let notices_before = collector.0.lock().expect("observer").clone();
        let module = Arc::new(tokio::sync::Mutex::new(owner));

        // Deterministically model a request paused after authentication and
        // before mutation. Keep the production auth snapshot; do not refresh
        // it in the fixture. This is authenticator + real-handler coverage,
        // not an executed HTTP router/extractor or lock-scheduling race.
        let old_revision = access.snapshot().1;
        let new_revision = access.set_group(
            "release",
            AccessGroup {
                members: vec![CAROL.to_string()],
                ..AccessGroup::default()
            },
        )?;
        assert!(new_revision > old_revision);
        let current_bob = access.view_for_subject(Some(BOB));
        assert!(current_bob.held_approver_ids().is_empty());
        assert!(current_bob.allows(crate::access::ACTION_GATING_DECIDE));
        let carol = authenticate(CAROL);
        assert_eq!(carol.principal.as_deref(), Some(CAROL));

        let (_temp_dir, runtime) =
            build_empty_console_test_runtime("gating-in-flight-revocation").await?;
        let refused = decide(&runtime, &module, &access, &bob, &pending).await;
        let after_refusal = module.lock().await.gating_state_snapshot();
        let notices_after_refusal = collector.0.lock().expect("observer").clone();
        let permitted = decide(&runtime, &module, &access, &carol, &pending).await;
        let after_permitted = module.lock().await.gating_state_snapshot();
        let repeated = decide(&runtime, &module, &access, &carol, &pending).await;
        let after_repeat = module.lock().await.gating_state_snapshot();
        let final_notices = collector.0.lock().expect("observer").clone();
        // Expected RED must still stop the real empty runtime before an
        // assertion fails; no operation is retried to manufacture success.
        let _ = runtime.handle().stop().await;

        assert!(
            refused["result"].is_null(),
            "revoked role approved: {refused}"
        );
        assert!(
            matches!(refused["error"]["code"].as_i64(), Some(-32030 | -32602)),
            "expected an access/approver refusal, not an infrastructure failure: {refused}",
        );
        assert_eq!(
            after_refusal, before,
            "exact pending, audit and ID state unchanged"
        );
        assert_eq!(notices_after_refusal, notices_before);
        assert!(notices_before.is_empty());
        let result: crate::GatingDecisionResult =
            serde_json::from_value(permitted["result"].clone())?;
        assert!(permitted["error"].is_null(), "{permitted}");
        assert_eq!(result.pending_id, pending);
        assert_eq!(result.action_id, evaluated.action_id);
        assert_eq!(result.approver_id, ROLE);
        assert_eq!(result.decision, crate::GatingDecision::Approve);
        assert_eq!(result.outcome, crate::GatingOutcome::Allowed);
        assert!(after_permitted.pending.is_empty());
        assert_eq!(after_permitted.audit.len(), before.audit.len() + 1);
        assert_eq!(
            &after_permitted.audit[..before.audit.len()],
            before.audit.as_slice()
        );
        let audit = after_permitted.audit.last().expect("decision audit");
        assert_eq!(audit.detail["deciding_principal"], json!(CAROL));
        assert_eq!(audit.detail["approver_id"], json!(ROLE));
        assert_eq!(audit.detail["approver_binding"], json!("held"));
        assert!(repeated["result"].is_null());
        assert_eq!(repeated["error"]["code"], json!(-32602));
        assert_eq!(
            after_repeat, after_permitted,
            "second decision changes nothing"
        );
        assert_eq!(
            final_notices,
            vec![GatingResolutionNotice {
                pending_id: pending,
                action_id: evaluated.action_id,
                approved: true,
                next_pending_id: None,
                cause: "approval_decided".to_string(),
            }]
        );
        Ok(())
    }

    /// DECISION (2026-07-06, meerkat-studio ask K2): console JSON-RPC internal
    /// errors DO disclose the failure reason. Every caller that reaches these
    /// handlers is an operator by construction — an auth-gated console 401s
    /// unauthenticated callers before dispatch, and an open console is a
    /// trusted-local deployment choice — while the previous redaction made
    /// every -32000 undiagnosable from the client (the K1 retire/respawn
    /// failures cost the reporter a day). The `error` field stays a stable
    /// kind discriminator; `console_send_public_message` keeps ITS redaction
    /// because that surface can reflect into agent-visible space.
    #[test]
    fn internal_error_carries_detail_and_stable_kind() {
        let response = super::internal_error(json!(7), "retire failed: backend says no");

        assert_eq!(response["error"]["code"], json!(-32000));
        assert_eq!(
            response["error"]["message"],
            json!("retire failed: backend says no")
        );
        assert_eq!(response["error"]["data"]["error"], json!("internal_error"));
        assert_eq!(
            response["error"]["data"]["detail"],
            json!("retire failed: backend says no")
        );
    }

